{
  "title": "Weekend Trip Todo List",
  "body": "<div class="todo-card">
  <header class="header">
    <div class="header-top">
      <div class="title-wrap">
        <span class="icon">🌲</span>
        <h2>Weekend Trip</h2>
      </div>
      <span id="count-display" class="count-badge"></span>
    </div>
    <div class="progress-track">
      <div id="progress-fill" class="progress-fill"></div>
    </div>
  </header>

  <div class="input-row">
    <input id="todo-input" type="text" placeholder="Add a new task..." />
    <button id="add-btn" class="add-btn">+ Add</button>
  </div>

  <div id="todo-list" class="todo-list"></div>

  <footer class="footer">
    <span class="footer-hint">Click task or checkbox to toggle</span>
    <button id="clear-completed-btn" class="clear-btn">Clear completed</button>
  </footer>
</div>",
  "css": "* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: #f4f6f8;
  color: #1f2937;
  padding: 16px;
}

.todo-card {
  max-width: 520px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.04);
  overflow: hidden;
  border: 1px solid #e5e7eb;
}

.header {
  padding: 20px 24px 16px;
  background: #fdfbf7;
  border-bottom: 1px solid #eef0f2;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.icon {
  font-size: 24px;
}

h2 {
  font-size: 20px;
  font-weight: 700;
  color: #1e3a2f;
  letter-spacing: -0.01em;
}

.count-badge {
  font-size: 13px;
  font-weight: 600;
  color: #2d6a4f;
  background: #e8f5e9;
  padding: 4px 10px;
  border-radius: 20px;
}

.progress-track {
  height: 6px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #40916c, #52b788);
  transition: width 0.25s ease;
}

.input-row {
  display: flex;
  gap: 8px;
  padding: 16px 20px;
  background: #ffffff;
  border-bottom: 1px solid #f3f4f6;
}

.input-row input {
  flex: 1;
  padding: 10px 14px;
  font-size: 14px;
  border: 1.5px solid #d1d5db;
  border-radius: 10px;
  outline: none;
  color: #1f2937;
  background: #fafafa;
}

.input-row input:focus {
  border-color: #2d6a4f;
  background: #ffffff;
}

.add-btn {
  padding: 10px 18px;
  font-size: 14px;
  font-weight: 600;
  color: #ffffff;
  background: #2d6a4f;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.add-btn:hover {
  background: #1b4332;
}

.todo-list {
  padding: 8px 12px;
  min-height: 140px;
}

.empty-state {
  text-align: center;
  padding: 36px 16px;
  font-size: 14px;
  color: #9ca3af;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 10px;
  transition: background 0.15s ease;
  border-bottom: 1px solid #f9fafb;
}

.todo-item:hover {
  background: #f8faf9;
}

.checkbox {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 2px solid #9ca3af;
  background: #ffffff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: bold;
  color: #ffffff;
  flex-shrink: 0;
  padding: 0;
  line-height: 1;
}

.checkbox.checked {
  background: #40916c;
  border-color: #40916c;
}

.item-text {
  flex: 1;
  font-size: 14px;
  line-height: 1.4;
  color: #374151;
  cursor: pointer;
  word-break: break-word;
}

.todo-item.completed .item-text {
  text-decoration: line-through;
  color: #9ca3af;
}

.delete-btn {
  background: transparent;
  border: none;
  color: #9ca3af;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  opacity: 0.6;
  transition: opacity 0.15s, color 0.15s;
}

.delete-btn:hover {
  opacity: 1;
  color: #e63946;
  background: #fef2f2;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  background: #fafbfc;
  border-top: 1px solid #f1f3f5;
  font-size: 12px;
  color: #6b7280;
}

.footer-hint {
  font-size: 12px;
}

.clear-btn {
  background: none;
  border: none;
  font-size: 12px;
  font-weight: 500;
  color: #6b7280;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
}

.clear-btn:hover {
  color: #b91c1c;
  background: #fee2e2;
}",
  "scripts": [
    "if (!state.items) {
  state.items = [
    { id: '1', text: 'Book cabin or campsite by the lake', done: true },
    { id: '2', text: 'Pack hiking boots, fleece & rain gear', done: false },
    { id: '3', text: 'Download offline trail maps & road trip playlist', done: false }
  ];
  state.inputText = '';
}

const remaining = state.items.filter(item => !item.done).length;
const total = state.items.length;
const completed = total - remaining;

const countBadge = root.byId['count-display'];
if (countBadge) {
  if (total === 0) {
    countBadge.text = '0 tasks';
  } else if (remaining === 0) {
    countBadge.text = 'All done! 🎉';
  } else {
    countBadge.text = `${remaining} ${remaining === 1 ? 'task' : 'tasks'} left`;
  }
}

const progressFill = root.byId['progress-fill'];
if (progressFill) {
  const pct = total === 0 ? 0 : Math.round((completed / total) * 100);
  progressFill.attrs.style = `width: ${pct}%`;
}

const inputEl = root.byId['todo-input'];
if (inputEl) {
  inputEl.attrs.value = state.inputText || '';
  inputEl.on = {
    input: (e) => {
      state.inputText = e.value;
    }
  };
}

const addItem = () => {
  const text = (state.inputText || '').trim();
  if (text.length > 0) {
    state.items.push({
      id: String(Date.now() + Math.random()),
      text: text,
      done: false
    });
    state.inputText = '';
    if (inputEl) {
      inputEl.attrs.value = '';
    }
  }
};

const addBtn = root.byId['add-btn'];
if (addBtn) {
  addBtn.on = {
    click: addItem
  };
}

const listEl = root.byId['todo-list'];
if (listEl) {
  if (state.items.length === 0) {
    listEl.children = [
      {
        tag: 'div',
        attrs: { class: 'empty-state' },
        text: 'All clear! Add a task above to plan your getaway.'
      }
    ];
  } else {
    listEl.children = state.items.map(item => {
      return {
        tag: 'div',
        attrs: { class: item.done ? 'todo-item completed' : 'todo-item' },
        children: [
          {
            tag: 'button',
            attrs: { class: item.done ? 'checkbox checked' : 'checkbox' },
            text: item.done ? '✓' : '',
            on: {
              click: () => {
                item.done = !item.done;
              }
            }
          },
          {
            tag: 'span',
            attrs: { class: 'item-text' },
            text: item.text,
            on: {
              click: () => {
                item.done = !item.done;
              }
            }
          },
          {
            tag: 'button',
            attrs: { class: 'delete-btn', title: 'Delete item' },
            text: '×',
            on: {
              click: () => {
                state.items = state.items.filter(i => i.id !== item.id);
              }
            }
          }
        ]
      };
    });
  }
}

const clearBtn = root.byId['clear-completed-btn'];
if (clearBtn) {
  clearBtn.attrs.style = completed > 0 ? 'display: inline-block;' : 'display: none;';
  clearBtn.on = {
    click: () => {
      state.items = state.items.filter(item => !item.done);
    }
  };
}"
  ]
}
